    42	  uint16_t crc = 0xffff;
    43	  size_t i;
    44	  int bit;
    45	
    46	  for (i = 0; i < len; i++)
    47	    {
    48	      crc ^= (uint16_t)data[i] << 8;
    49	      for (bit = 0; bit < 8; bit++)
    50	        {
    51	          crc = (crc & 0x8000) != 0 ? (uint16_t)((crc << 1) ^ 0x1021)
    52	                                    : (uint16_t)(crc << 1);
    53	        }
    54	    }
    55	
    56	  return crc;
    57	}
