struct lcd_info_s {
  uint32_t width;
  uint32_t height;
  uint32_t bpp;
  uint32_t fmt;
};

static int g_lcd_backlight_fd = -1;

static int lcd_set_brightness(unsigned long percent) {
  struct pwm_info_s info;
  int ret;

  if (percent < 20 || percent > 100) {
    return -EINVAL;
  }

  if (g_lcd_backlight_fd < 0) {
    g_lcd_backlight_fd = open("/dev/pwm0", O_RDWR);
    if (g_lcd_backlight_fd < 0) {
      return -errno;
    }
  }

  info.frequency = 60000;
  info.duty = (uint32_t)(percent * 0xffffu / 100u);
  ret = ioctl(g_lcd_backlight_fd, PWMIOC_SETCHARACTERISTICS,
              (unsigned long)&info);
  if (ret < 0) {
    return -errno;
  }

  ret = ioctl(g_lcd_backlight_fd, PWMIOC_START, 0);
  return ret < 0 ? -errno : OK;
}

