struct aic_pwm_lowerhalf_s {
  struct pwm_lowerhalf_s lower;
  uint8_t channel;
};

static struct aic_pwm_lowerhalf_s g_aic_pwm0;
#ifdef CONFIG_AIC_USING_PWM1
static struct aic_pwm_lowerhalf_s g_aic_pwm1;
#endif

static struct aic_pwm_lowerhalf_s *pwm_priv(struct pwm_lowerhalf_s *dev) {
  return (struct aic_pwm_lowerhalf_s *)dev;
}

static int pwm_setup(struct pwm_lowerhalf_s *dev) {
  struct aic_pwm_lowerhalf_s *priv = pwm_priv(dev);
  struct aic_pwm_action action0 = {/*       CBD,          CBU,          CAD, */
                                   PWM_ACT_NONE, PWM_ACT_NONE, PWM_ACT_NONE,
                                   /*      CAU,           PRD,         ZRO  */
                                   PWM_ACT_LOW, PWM_ACT_NONE, PWM_ACT_HIGH};
  struct aic_pwm_action action1 = {/*       CBD,          CBU,          CAD, */
                                   PWM_ACT_NONE, PWM_ACT_LOW, PWM_ACT_NONE,
                                   /*      CAU,           PRD,         ZRO  */
                                   PWM_ACT_NONE, PWM_ACT_NONE, PWM_ACT_HIGH};

  hal_pwm_ch_init(priv->channel, PWM_MODE_UP_COUNT, 0, &action0, &action1);
  return OK;
}

static int pwm_shutdown(struct pwm_lowerhalf_s *dev) {
  struct aic_pwm_lowerhalf_s *priv = pwm_priv(dev);

  hal_pwm_disable(priv->channel);
  hal_pwm_ch_deinit(priv->channel);
  return OK;
}

static int pwm_start(struct pwm_lowerhalf_s *dev,
                     const struct pwm_info_s *info) {
  struct aic_pwm_lowerhalf_s *priv = pwm_priv(dev);
  int ret = OK;
  uint32_t duty_ns, period_ns;

  period_ns = 1000000000 / info->frequency;
  duty_ns = (info->duty * period_ns) / 0xffff;

  ret = hal_pwm_set(priv->channel, duty_ns, period_ns, PWM_SET_CMPA_CMPB);
  if (ret < 0) {
    return ret;
  }

  ret = hal_pwm_enable(priv->channel);
  if (ret < 0) {
    return ret;
  }

  return OK;
}

static int pwm_stop(struct pwm_lowerhalf_s *dev) {
  struct aic_pwm_lowerhalf_s *priv = pwm_priv(dev);

  return hal_pwm_disable(priv->channel);
}

static int pwm_ioctl(struct pwm_lowerhalf_s *dev, int cmd, unsigned long arg) {
  return -ENOTTY;
}

static const struct pwm_ops_s g_pwmops = {
    .setup = pwm_setup,
    .shutdown = pwm_shutdown,
    .start = pwm_start,
    .stop = pwm_stop,
    .ioctl = pwm_ioctl,
};

