#include <string.h>
#include <syslog.h>

#include <nuttx/timers/pwm.h>

#include "velacare_display.h"

#define VELACARE_BACKLIGHT_DEVICE "/dev/pwm0"
#define VELACARE_BACKLIGHT_HZ 1000

static int g_pwm_fd = -1;
static int g_brightness = 80;

int velacare_display_init(void)
{
  if (g_pwm_fd >= 0)
    {
      return 0;
    }

  g_pwm_fd = open(VELACARE_BACKLIGHT_DEVICE, O_RDWR);
  if (g_pwm_fd < 0)
    {
      int error = -errno;
      syslog(LOG_ERR, "[VelaCare] open %s failed: %d\n",
             VELACARE_BACKLIGHT_DEVICE, error);
      return error;
    }

  return 0;
}

int velacare_display_set_brightness(int value)
{
  struct pwm_info_s info;
  struct pwm_info_s applied;
  uint32_t expected_duty;
  int ret;

  if (value < 20 || value > 100)
    {
      return -EINVAL;
    }

  if (g_pwm_fd < 0)
    {
      ret = velacare_display_init();
      if (ret < 0)
        {
          return ret;
        }
    }

  memset(&info, 0, sizeof(info));
  expected_duty = (uint32_t)value * 0xffffu / 100u;
  info.frequency = VELACARE_BACKLIGHT_HZ;
  info.duty = expected_duty;

