static void setting_slider_event(lv_event_t *event)
{
  lv_event_code_t code;
  int index;
  int value;
  lv_obj_t *slider;

  code = lv_event_get_code(event);
  if ((code != LV_EVENT_VALUE_CHANGED && code != LV_EVENT_RELEASED) ||
      g_ui == NULL)
    {
      return;
    }

  index = (int)(intptr_t)lv_event_get_user_data(event);
  slider = lv_event_get_target_obj(event);
  value = lv_slider_get_value(slider);
  if (code == LV_EVENT_VALUE_CHANGED && index == 0)
    {
      lv_label_set_text_fmt(g_ui->volume_label, "提示音量 %d%%", value);
    }
  else if (code == LV_EVENT_VALUE_CHANGED)
    {
      lv_label_set_text_fmt(g_ui->brightness_label,
                            "屏幕亮度 %d%%", value);
    }
  else
    {
      int ret = index == 0 ? velacare_buzzer_set_volume(value) :
                             velacare_display_set_brightness(value);

      if (ret == 0)
        {
          ret = index == 0 ? velacare_settings_set_volume(value) :
                             velacare_settings_set_brightness(value);
        }
      lv_label_set_text(g_ui->setting_notice,
                        ret == 0 ? "已保存，重启后有效" :
                                   "应用失败，请重试");
      lv_obj_set_style_text_color(g_ui->setting_notice,
                                  lv_color_hex(ret == 0 ? 0x15803d :
                                                           0xb91c1c), 0);
    }
}

